import { platform } from '@/lib/platform/index.js';
import { settingsPath } from './paths.js';

export type Assistant = 'chatgpt' | 'claude' | 'claudeCode';

/*
 * Where each assistant connects Lexpad (Lexpad's listing in ChatGPT's
 * Plugins Directory, published 2026-10-27 as plugin 1.0.3; Lexpad's page in
 * Claude's connector directory), and the public page about assistants.
 * These are other services' addresses (and the landing site's), not Lexpad
 * data: nothing on the server knows them, so they are named here once. The
 * ChatGPT id is the one OpenAI gave the listing ("View plugin" in the
 * developer dashboard); it stays the same across plugin versions.
 */
export const CHATGPT_PLUGINS_URL =
  'https://chatgpt.com/plugins/plugin_asdk_app_6ac15aade0e8819181a05df59f14f4a3';
export const CLAUDE_DIRECTORY_URL = 'https://claude.ai/directory/lexpad';
export const ASSISTANTS_PAGE_URL = 'https://lexpad.app/features/assistants';

/** `/settings/connected-apps?connect=1` opens the connect steps straight away. */
export const CONNECT_PARAM = 'connect';

/** The address that lands on the connect steps, for rows elsewhere in the app. */
export const CONNECT_ASSISTANT_PATH = `${settingsPath('connected-apps')}?${CONNECT_PARAM}=1`;

/**
 * The MCP endpoint lives on the API host, so the address is read from the
 * API address this build was given rather than written down.
 */
export function mcpAddress(): string {
  return new URL('/mcp', platform.env.apiUrl || window.location.origin).href;
}
